UPDATE sys_social_tag
SET tag_name = #{t.tagName},
    status = #{t.status},
    source_hash = #{t.sourceHash},
    last_seen_run_id = #{t.lastSeenRunId},
    update_time = NOW()
WHERE tenant_id = #{t.tenantId}
  AND connection_id = #{t.connectionId}
  AND external_tag_id = #{t.externalTagId}
  AND del_flag = 0

