UPDATE sys_user_social
SET source_hash = #{sourceHash},
    last_sync_time = NOW(),
    external_status = 'ACTIVE'
WHERE tenant_id = #{tenantId}
  AND connection_id = #{connectionId}
  AND uuid = #{uuid}
  AND managed_by_sync = 1
  AND del_flag = 0

UPDATE sys_user_social
SET external_status = #{externalStatus},
    last_sync_time = NOW()
WHERE tenant_id = #{tenantId}
  AND connection_id = #{connectionId}
  AND uuid = #{uuid}
  AND managed_by_sync = 1
  AND del_flag = 0
